import type { IeltsSelfTestLocale } from './ieltsSaqrPractice';

export type IeltsPracticeTrack = 'academic' | 'general';
export type IeltsPracticeStage = 'foundation' | 'developing' | 'mock';
export type IeltsWritingTask = 1 | 2;

/**
 * Original IELTS-format-inspired simulations, not official IELTS or Cambridge
 * questions. Generated by the EXISTING Saqr assistant through its regular
 * send handler. Source pages give task categories only, never copyrighted
 * practice questions/recordings to copy.
 */
export const IELTS_OFFICIAL_SAMPLE_LINKS = [
  {id:'listening',ar:'نماذج Listening الرسمية',en:'Official Listening sample tasks',
    url:'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test'},
  {id:'academic-reading',ar:'نماذج Academic Reading الرسمية',en:'Official Academic Reading samples',
    url:'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test'},
  {id:'general-reading',ar:'نماذج General Training Reading الرسمية',en:'Official General Training Reading samples',
    url:'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/general-training-test'},
  {id:'academic-writing',ar:'نماذج Academic Writing الرسمية',en:'Official Academic Writing samples',
    url:'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test'},
  {id:'general-writing',ar:'نماذج General Training Writing الرسمية',en:'Official General Training Writing samples',
    url:'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/general-training-test'},
  {id:'writing-criteria',ar:'معايير تقييم Writing الرسمية',en:'Official Writing assessment criteria',
    url:'https://ielts.org/take-a-test/preparation-resources/writing-test-resources'},
] as const;

const samplePage = (track:IeltsPracticeTrack) =>
  'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/' +
  (track==='academic'?'academic-test':'general-training-test');

const language = (locale:IeltsSelfTestLocale) => locale==='ar'
  ? 'Use natural, friendly Emirati Arabic for coaching, but every exam passage, question, task and answer must be in formal standard English.'
  : 'Use formal, clear English for exam content and friendly English for coaching.';

export function ieltsReadingPracticeRequest(
  locale:IeltsSelfTestLocale,
  track:IeltsPracticeTrack,
  stage:IeltsPracticeStage,
):string {
  const ranges = {
    foundation: {words:'180–230',count:4,label:'foundation practice'},
    developing:{words:'300–380',count:7,label:'developing practice'},
    mock:{words:'550–650',count:10,label:'extended mini-mock'}
  } as const;
  const chosen=ranges[stage];
  return [
    'SAQR IELTS READING — ORIGINAL EXAM-STYLE PRACTICE, NOT AN OFFICIAL IELTS EXAM.',
    'Mode: '+track.toUpperCase()+'. Difficulty: '+chosen.label+'.',
    'Official IELTS sample task types for reference: '+samplePage(track),
    'Use the official source ONLY for format and question categories. DO NOT reproduce its copyrighted passages, sample questions, answer keys or scripts.',
    'Do not search the school catalogue, do not claim access to the 24 Cambridge PDFs, do not assign an official IELTS band.',
    language(locale),
    track==='academic'
      ? 'Generate an entirely ORIGINAL informational / analytical passage in a magazine, academic or journal-like style for a non-specialist reader; avoid fictional real-world statistics presented as facts.'
      : 'Generate entirely ORIGINAL General Training everyday reading material: realistic notices, emails, instructions or workplace/public-information texts. Longer levels may contain multiple connected workplace or public texts.',
    'Choose a distinct topic from transport, environmental management, urban design, library technology, education, science communication, or community services. Avoid repeating topics if the student requests another simulation.',
    'START by writing one coherent passage of about '+chosen.words+' words in full, then '+chosen.count+' clearly numbered questions in a MIX of official-inspired formats: True/False/Not Given, matching headings, multiple choice, sentence completion, or short answer.',
    'Make answers unambiguous and traceable to the passage; distinguish Not Given from False correctly; follow announced word limits exactly.',
    'Do NOT reveal the answer key until the student responds. Ask the student to submit numbered answers; evaluate them against your passage, cite supporting sentences, teach vocabulary, and then offer the next practice text.',
    'This is a smaller, custom training simulation: it is not a complete official 60-minute, 40-question Reading test.'
  ].join('\n\n');
}

export function ieltsWritingPracticeRequest(
  locale:IeltsSelfTestLocale,
  track:IeltsPracticeTrack,
  stage:IeltsPracticeStage,
  task:IeltsWritingTask,
):string {
  const isTask1=task===1;
  return [
    'SAQR IELTS WRITING — ORIGINAL EXAM-STYLE PRACTICE, NOT OFFICIAL IELTS TASK CONTENT.',
    'Track: '+track+'. Task: '+task+'. Learning stage: '+stage+'.',
    'Official task formats and sample material (view at the original publisher only): '+samplePage(track),
    'Official writing criteria: https://ielts.org/take-a-test/preparation-resources/writing-test-resources',
    'Use official IELTS task structure and grading criteria only. Never copy any official copyrighted sample question or model answer.',
    'Do not search the school catalogue, do not claim access to PDF textbook pages, do not assign an official IELTS band or promise a certified score.',
    language(locale),
    isTask1 && track==='academic'
      ? 'Create an ORIGINAL IELTS Academic Writing Task 1 with a self-contained small numeric data TABLE (at least four rows and two comparable periods), clear units, a title and internally consistent figures. Ask the student to summarise and compare key features. Do not refer to an unseen chart, image or diagram. Say "Write at least 150 words; suggested time: 20 minutes."'
      : isTask1
        ? 'Create an ORIGINAL General Training Task 1 letter-writing situation with a clear recipient, 3 distinct bullet-point requirements and appropriate formal / semi-formal / informal tone. Say "Write at least 150 words; suggested time: 20 minutes."'
        : 'Create an ORIGINAL Writing Task 2 essay prompt requiring an argument, discussion of views or problem-solution evaluation on education, public services, technology, environment or work. Say "Write at least 250 words; suggested time: 40 minutes."',
    stage==='foundation'
      ? 'Use clear, manageable content and explain the task instructions briefly, but do not provide the finished answer.'
      : stage==='mock'
        ? 'Use authentic IELTS-like task complexity and time guidance without claiming the task is an official examination.'
        : 'Use moderate task complexity and normal IELTS-style instructions.',
    'Present just the task and timing/word-count guidance FIRST. Wait for the student to write their own response.',
    'After the response, give structured formative feedback under four real IELTS Writing criterion headings: Task Achievement/Task Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy.',
    'Check approximate word count; identify concrete grammar / spelling / structure issues with improved alternatives; give a stronger sample paragraph ONLY after reviewing the learner’s own attempt.',
    'Clearly label any score as a non-official practice estimate and avoid giving a numerical IELTS band unless explicitly requested with a careful uncertainty warning.',
  ].join('\n\n');
}

export function ieltsWrittenSpeakingRequest(locale:IeltsSelfTestLocale):string {
  return [
    'SAQR IELTS SPEAKING — TEXT-ONLY INTERACTIVE CHAT SIMULATION.',
    'Important: This is an ORIGINAL WRITTEN conversation inspired by the official IELTS Speaking structure, NOT an official IELTS test. There is NO microphone, audio recording, speech recognition or spoken pronunciation evaluation.',
    'The speaking format is shared between Academic and General Training. Reference: https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test',
    language(locale),
    'Be a friendly English-speaking IELTS-style examiner for a practice text chat. You ask in ENGLISH and the learner TYPES in ENGLISH. One question per chat turn and WAIT for their typed answer.',
    'Begin immediately with an original Part 1 question about everyday topics (hobbies, studies, local transport, reading or work). Avoid asking the learner to choose the track first.',
    'Ask 4–5 Part 1 questions, moving naturally to a Part 2 ORIGINAL cue-card topic: what to describe, who/where/why, and what they learned; offer 1 minute of preparation and ask for one extended written response.',
    'Follow with 4–5 Part 3 discussion questions about abstract ideas linked to the cue card; wait after each response.',
    'At the end of each section, give useful short feedback on vocabulary, grammatical accuracy, ideas and coherence while preserving conversational flow. Only point out spelling / grammar errors actually present in the text.',
    'DO NOT claim you assessed pronunciation, actual spoken fluency, delivery, accent or voice because all answers are typed. Do not assign an official IELTS band or suggest the learner has taken a certified Speaking test.',
    'Never search the school book catalogue. Do not disturb any other Saqr functions.',
  ].join('\n\n');
}
